-- interview-flyback-fix.sql — q28–q32 共用底圖：字級 7→10、6 個標籤挪離走線
-- 為什麼要跑：這五筆 DB 已含舊圖，前端回填只補「沒有圖」的答案，不會覆蓋既有圖。
-- 改了什麼：字級 +3（桌機有效字級 5.1px → 9.9px），Q1/Cps/Cout/400V/VDD/D3 六個標籤移開走線。
--           元件座標與拓樸一字未動（line/rect/polygon/path 逐字比對相同）。
-- 驗證：瀏覽器 getBBox+getCTM 實測，14 張圖 / 281 個文字 / 重疊 0。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q28：一次側主迴路 + 高壓線段
update public.interview_questions set
  answer = case when answer like '%<svg%'
    then regexp_replace(answer, $re$<div class="exam-diagram-box">.*</svg></div>$re$, n.box)
    else answer end,
