 where question like $q$%輔助繞組還沒有電%$q$;

-- 驗收：五列都要 zh_font10 = t（新圖字級 10，舊圖是 7）
select left(question, 20) as q,
       answer like '%font-size="10"%' as zh_font10,
       answer like '%y="166"%' as q1_label_moved,
       length(answer) as len
  from public.interview_questions
 where question like $q$%開關切換的大電流路徑%$q$
    or question like $q$%輸出整流大電流路徑%$q$
    or question like $q$%寄生電容跑到二次側%$q$
    or question like $q$%TL431 與光耦%$q$
    or question like $q$%輔助繞組還沒有電%$q$;
